import requests
B="https://www.ebi.ac.uk/chembl/api/data"
s=requests.get(f"{B}/molecule/search.json?q=metformin&limit=20",timeout=60).json()
ids=[]
for mo in s["molecules"]:
    print(mo["molecule_chembl_id"], mo.get("pref_name"), "phase",mo.get("max_phase"))
    ids.append(mo["molecule_chembl_id"])
print("---mechanisms across these ids---")
for i in ids:
    m=requests.get(f"{B}/mechanism.json?molecule_chembl_id={i}&limit=50",timeout=60).json()
    if m["page_meta"]["total_count"]:
        for x in m["mechanisms"]:
            print(i, "|", x.get("mechanism_of_action"), "|", x.get("action_type"), "|", x.get("target_chembl_id"))

